CREATE FUNCTION app.holiday_replacement_state_only() RETURNS trigger LANGUAGE plpgsql AS $f$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM app.holidays h WHERE h.id = NEW.holiday_id AND h.level = 'STATE' AND h.removed_at IS NULL) THEN
    RAISE EXCEPTION 'only a state holiday can be replaced by a client' USING ERRCODE = '23514', CONSTRAINT = 'holiday_replacements_state_only';
  END IF;
  IF NEW.replacement_date = (SELECT date FROM app.holidays WHERE id = NEW.holiday_id) THEN
    RAISE EXCEPTION 'the replacement day must differ from the holiday' USING ERRCODE = '23514', CONSTRAINT = 'holiday_replacements_other_day';
  END IF;
  RETURN NEW;
END $f$
